import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  interpolateColors,
} from '../remotionShim';


export type EyeIconAnimationProps = Record<string, any>;

const EyeIconAnimation: React.FC<EyeIconAnimationProps> = ({
  backgroundColor = "#f5f5f5",
  transparentBackground = false,
  durationInSeconds = 6,
  eyeColor = "#808080",
  eyeshadowColor = "#404040",
  bottomLinerColor = "#222222",
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Parser-safe background logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  const totalFrames = fps * durationInSeconds;

  // Monotonic animation phases
  const phase1Start = 0;
  const phase1End = Math.max(1, totalFrames * 0.25);
  const phase2Start = phase1End;
  const phase2End = Math.max(phase2Start + 1, totalFrames * 0.6);
  const phase3Start = Math.max(phase2End + 1, totalFrames * 0.65);
  const phase3End = Math.max(phase3Start + 1, totalFrames * 0.95);

  // Phase 1: Base eyelid transitions from white to dark (eyeshadow application)
  const eyelidColor = interpolateColors(
    frame,
    [phase1Start, phase1End],
    ["#ffffff", eyeshadowColor]
  );

  // Phase 2: Soft gradient expands outwards from the crease (Spread out and softer)
  // Shifted up and out to the right
  const gradientOpacity = interpolate(frame, [phase2Start, phase2End], [0, 0.95], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const gradientTopX = interpolate(frame, [phase2Start, phase2End], [0, 300], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const gradientTopY = interpolate(frame, [phase2Start, phase2End], [-280, -750], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  // Phase 3: Bottom line darkens and blurs (tight gradient effect)
  const bottomOpacity = interpolate(frame, [phase3Start, phase3End], [0, 0.4], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const bottomDepth = interpolate(frame, [phase3Start, phase3End], [155, 190], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const bottomBlur = interpolate(frame, [phase3Start, phase3End], [0.001, 6], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      <svg
        width={width * 0.6}
        height={height * 0.6}
        viewBox="-300 -300 600 600"
        style={{ overflow: "visible", transition: "none" }}
      >
        <defs>
          <clipPath id="eye-clip">
            <path d="M -250 0 Q 0 -150 250 0 Q 0 150 -250 0" />
          </clipPath>

          {/* Bounding box gradient: y1="1" (bottom/lashline), y2="0" (top/expanding edge) */}
          <linearGradient id="eyeshadow-grad" x1="0" y1="1" x2="0.2" y2="0">
            <stop offset="0%" stopColor={eyeshadowColor} stopOpacity={gradientOpacity} />
            <stop offset="100%" stopColor={eyeshadowColor} stopOpacity={0} />
          </linearGradient>

          {/* Top blur filter for softer eyeshadow spread - Expanded dimensions to prevent clipping and increased blur */}
          <filter id="top-blur" x="-100%" y="-100%" width="300%" height="300%">
            <feGaussianBlur stdDeviation="50" />
          </filter>

          <filter id="bottom-blur">
            <feGaussianBlur stdDeviation={bottomBlur} />
          </filter>
        </defs>

        {/* Base Sclera (Eye White) - Made slightly rounder */}
        <path
          d="M -250 0 Q 0 -150 250 0 Q 0 150 -250 0"
          fill="#ffffff"
          stroke="#1a1a1a"
          strokeWidth="6"
          style={{ transition: "none" }}
        />

        {/* Static Iris & Pupil (Clipped to eye shape, slightly scaled up for rounder eye) */}
        <g clipPath="url(#eye-clip)" style={{ transition: "none" }}>
          <circle cx="0" cy="0" r="90" fill={eyeColor} />
          {/* Subtle iris texture ring */}
          <circle
            cx="0"
            cy="0"
            r="78"
            fill="none"
            stroke="#ffffff"
            strokeOpacity={0.15}
            strokeWidth="10"
          />
          <circle cx="0" cy="0" r="38" fill="#0d0d0d" />
          {/* Catchlights */}
          <circle cx="26" cy="-30" r="16" fill="#ffffff" opacity={0.85} />
          <circle cx="-30" cy="22" r="7" fill="#ffffff" opacity={0.5} />
        </g>

        {/* Top Eyelid Base (White -> Dark Transition) - Made bigger */}
        <path
          d="M -250 0 Q 0 -150 250 0 Q 0 -280 -250 0"
          fill={eyelidColor}
          style={{ transition: "none" }}
        />

        {/* Top Eyelid Expanding Soft Gradient - With added blur and shifted up/right */}
        {frame > phase1End && (
          <path
            d={`M -250 0 Q 0 -150 250 0 Q ${gradientTopX} ${gradientTopY} -250 0`}
            fill="url(#eyeshadow-grad)"
            filter="url(#top-blur)"
            style={{ transition: "none" }}
          />
        )}

        {/* Top Lashline Definition (Keeps the edge sharp over the shadow) */}
        <path
          d="M -250 0 Q 0 -150 250 0"
          fill="none"
          stroke="#1a1a1a"
          strokeWidth="8"
          strokeLinecap="round"
          style={{ transition: "none" }}
        />

        {/* Bottom Liner / Shadow (Darkens and Blurs) - Extended fully to corners */}
        {frame > phase3Start && (
          <path
            d={`M -250 0 Q 0 150 250 0 Q 0 ${bottomDepth} -250 0`}
            fill={bottomLinerColor}
            opacity={bottomOpacity}
            filter="url(#bottom-blur)"
            style={{ transition: "none" }}
          />
        )}
      </svg>
    </AbsoluteFill>
  );
};

export default EyeIconAnimation;